<div class="dashboard-heading"><div><span class="eyebrow">OBSERVABILIDADE</span><h2>Saúde da plataforma</h2><p>Logs, alertas, serviços e backups em um único painel.</p></div><span class="date-chip">Atualizado em <?=date('d/m/Y H:i')?></span></div>
<section class="panel"><div class="panel-head"><div><small>SERVIÇOS</small><h3>Última verificação</h3></div></div><div class="monitor-grid"><?php if(!$health):?><p>Nenhuma verificação executada ainda.</p><?php endif;?><?php foreach($health as $check):?><article class="monitor-card monitor-card--<?=e($check['status'])?>"><span><?=e(strtoupper($check['status']))?></span><strong><?=e($check['service'])?></strong><small><?=date('d/m/Y H:i:s',strtotime($check['checked_at']))?><?=$check['response_time_ms']!==null?' · '.(int)$check['response_time_ms'].' ms':''?></small></article><?php endforeach;?></div></section>
<div class="dashboard-columns monitoring-columns"><section class="panel"><div class="panel-head"><div><small>ALERTAS</small><h3>Ocorrências operacionais</h3></div></div><div class="table-wrap"><table><thead><tr><th>Severidade</th><th>Origem</th><th>Mensagem</th><th>Ocorrências</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($alerts as $alert):?><tr><td><span class="badge badge--<?=e($alert['severity']==='critical'?'failed':'pending')?>"><?=e($alert['severity'])?></span></td><td><?=e($alert['source'])?></td><td><?=e($alert['message'])?><small><?=date('d/m/Y H:i',strtotime($alert['last_occurred_at']))?></small></td><td><?=(int)$alert['occurrence_count']?></td><td><?=e($alert['status'])?></td><td><?php if($alert['status']==='open'):?><form method="post" action="<?=e(url('/admin/monitoramento/alertas/'.$alert['id'].'/resolver'))?>"><?=csrf_field()?><button class="text-button">Resolver</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><div class="panel-head"><div><small>BACKUPS</small><h3>Execuções recentes</h3></div></div><?php if(!$backups):?><p>Nenhum backup executado.</p><?php endif;?><?php foreach($backups as $backup):?><div class="backup-row"><span class="badge badge--<?=e($backup['status']==='completed'?'completed':($backup['status']==='failed'?'failed':'pending'))?>"><?=e($backup['status'])?></span><div><strong><?=e($backup['filename']?:'Backup em processamento')?></strong><small><?=date('d/m/Y H:i',strtotime($backup['started_at']))?><?=$backup['size_bytes']?' · '.number_format((int)$backup['size_bytes']/1048576,2,',','.').' MB':''?></small></div></div><?php endforeach;?></section></div>
<section class="panel"><div class="panel-head"><div><small>FILA ASSÍNCRONA</small><h3>Últimos 50 jobs</h3></div><span><?php foreach($queueSummary as $item):?><?=e($item['status'])?>: <?=(int)$item['total']?> &nbsp;<?php endforeach;?></span></div><?php if(!$jobs):?><p>Nenhum job processado ou aguardando.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>ID</th><th>Fila</th><th>Tipo</th><th>Status</th><th>Tentativas</th><th>Disponível</th><th>Erro</th><th></th></tr></thead><tbody><?php foreach($jobs as $job):?><tr><td>#<?=(int)$job['id']?></td><td><?=e($job['queue'])?></td><td><?=e($job['job_type'])?></td><td><span class="badge badge--<?=e($job['status']==='completed'?'completed':($job['status']==='failed'?'failed':'pending'))?>"><?=e($job['status'])?></span></td><td><?=(int)$job['attempts']?>/<?=(int)$job['max_attempts']?></td><td><?=date('d/m/Y H:i:s',strtotime($job['available_at']))?></td><td><?=e($job['last_error']?:'—')?></td><td><?php if($job['status']==='failed'):?><form method="post" action="<?=e(url('/admin/monitoramento/jobs/'.$job['id'].'/tentar-novamente'))?>"><?=csrf_field()?><button class="text-button">Tentar novamente</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="panel-head"><div><small>LOGS CENTRALIZADOS</small><h3>Últimos 100 eventos</h3></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Nível</th><th>Canal</th><th>Evento</th><th>Requisição</th><th>ID</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=date('d/m/Y H:i:s',strtotime($log['created_at']))?></td><td><span class="badge badge--<?=e(in_array($log['level'],['error','critical'],true)?'failed':($log['level']==='warning'?'pending':'active'))?>"><?=e($log['level'])?></span></td><td><?=e($log['channel'])?></td><td><?=e($log['message'])?></td><td><?=e(trim(($log['request_method']??'').' '.($log['request_path']??''))?:'—')?></td><td><code><?=e($log['request_id']?:'—')?></code></td></tr><?php endforeach;?></tbody></table></div></section>
